source = source.strip()
target = target.strip()
if not edges:
    raise ValueError("Edges list cannot be empty")

G = nx.Graph()
for edge in edges:
    if len(edge) < 2:
        raise ValueError("Each edge must have at least two nodes")
    if len(edge) == 2:
        G.add_edge(edge[0], edge[1])
    else:
        G.add_edge(edge[0], edge[1], weight=edge[2])

try:
    weight = nx.dijkstra_path_length(G, source, target, weight='weight')
    path_exists = True
    display = f"Shortest path weight from {source} to {target} is {weight}"
except nx.NetworkXNoPath:
    weight = None
    path_exists = False
    display = "No path exists"
except nx.NodeNotFound:
    raise ValueError(f"Source or target node not found in graph: {source}, {target}")

return {"weight": weight, "path_exists": path_exists, "display": display}

G = nx.Graph()
for edge in edges:
    if len(edge) != 3:
        raise ValueError("Each edge must be [node1, node2, weight]")
    G.add_edge(edge[0], edge[1], weight=edge[2])

T = nx.minimum_spanning_tree(G, weight='weight')
total_weight = sum(d['weight'] for u, v, d in T.edges(data=True))
mst_edges = [[u, v, w] for u, v, w in T.edges(data='weight')]
display = f"The total weight of the MST is {total_weight}"

return {"total_weight": total_weight, "mst_edges": mst_edges, "display": display}

source = source.strip()
target = target.strip()
G = nx.DiGraph()
for edge in edges:
    if len(edge) != 3:
        raise ValueError("Each edge must be [node1, node2, capacity]")
    G.add_edge(edge[0], edge[1], capacity=edge[2])

try:
    flow_value = nx.maximum_flow_value(G, source, target, capacity='capacity')
    display = f"The maximum flow from {source} to {target} is {flow_value}"
except (nx.NetworkXError, nx.NodeNotFound):
    raise ValueError(f"Error computing max flow: source or target node not found or graph structure invalid")

return {"flow_value": flow_value, "display": display}

G = nx.Graph()
if weight_attribute:
    for edge in edges:
        if len(edge) != 3:
            raise ValueError("Edges must be [node1, node2, weight] when weight_attribute is provided")
        G.add_edge(edge[0], edge[1], weight=edge[2])
else:
    G.add_edges_from(edges)

centralities = nx.betweenness_centrality(G, weight=weight_attribute)
if not centralities:
    raise ValueError("Graph has no nodes to compute centrality")

node = max(centralities, key=centralities.get)
centrality_value = centralities[node]
display = f"Node {node} has the highest betweenness centrality of {centrality_value}"

return {"node": node, "centrality_value": centrality_value, "display": display}
